function notify(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function snapshot(){history.push(JSON.stringify(project));if(history.length>30)history.shift()}
let autosaveRevision = 0;
let autosaveState = {projectId: null, status: 'idle', error: ''};

function autosaveMarkup() {
  const state = autosaveState.projectId === project.id ? autosaveState : {status: 'idle'};
  if (state.status === 'failed') {
    return `<span class="save-warning" role="status" title="${esc(state.error)}">自动保存失败</span>
      <button class="btn small" data-action="retry-autosave">重试</button>
      <button class="btn small" data-action="save-project-copy">另存为</button>`;
  }
  return {idle: '本机工程', pending: '正在保存…', saved: '已自动保存至本机'}[state.status];
}

function updateAutosaveState(revision, projectId, status, error = '') {
  if (revision !== autosaveRevision || projectId !== project.id) return;
  autosaveState = {projectId, status, error};
  const indicator = $('.save-indicator');
  if (indicator) indicator.innerHTML = autosaveMarkup();
}

async function save() {
  const revision = ++autosaveRevision;
  const projectId = project.id;
  updateAutosaveState(revision, projectId, 'pending');
  try {
    if (window.desktop) {
      const result = window.desktop.autosaveProject
        ? await window.desktop.autosaveProject(project)
        : await window.desktop.autosave(JSON.stringify(project));
      if (!result.ok) throw Error(result.error || '写入失败');
    } else localStorage.setItem(KEY, JSON.stringify(project));
    updateAutosaveState(revision, projectId, 'saved');
  } catch (error) {
    updateAutosaveState(revision, projectId, 'failed', error.message);
  }
}
function change(fn,render=true){snapshot();fn();save();if(render)draw()}
